import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long p = scanner.nextLong();
        long k = scanner.nextLong();
        long MOD = 1000000007;

        if (k != 1 && k != 0) {
            boolean[] mark = new boolean[(int)p];
            for (int i = 0; i < p; i++) {
                mark[i] = true;
            }

            long total_result = 1;
            for (long start = 1; start < p; start++) {
                if (mark[(int)start]) {
                    long val = start;
                    do {
                        val = (val * k) % p;
                        mark[(int)val] = false;
                    } while (val != start);
                    total_result = (total_result * p) % MOD;
                }
            }
            System.out.println(total_result);
        } else if (k == 1) {
            long res = 1;
            for (long i = 0; i < p; i++) {
                res = (res * p) % MOD;
            }
            System.out.println(res);
        } else {
            long res = 1;
            for (long i = 0; i < p - 1; i++) {
                res = (res * p) % MOD;
            }
            System.out.println(res);
        }
        scanner.close();
    }
}
